    // ─────────── فصل ۱: رباخوار ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Pawnbroker", titlePersian = "رباخوار",
        paragraphs = listOf(
            StoryParagraph("In the beginning of July, during an extremely hot spell, towards evening, a young man came out of the garret in which he lodged in a certain house in S—— Lane and walked slowly, as though in hesitation, towards K—— Bridge.", "در آغاز ماه ژوئیه، در گرمای شدیدی، به سوی غروب، جوانی از اتاق زیرشیروانی که در آن در خانه‌ای در کوچه‌ای در پترزبورگ کرایه کرده بود بیرون آمد و آهسته، گویی با تردید، به سمت پل ک—— به راه افتاد."),
            StoryParagraph("He had successfully avoided meeting his landlady on the staircase, and he was glad of it, for he owed her rent and was in debt to her besides.", "او موفق شده بود از روبرو شدن با صاحب‌خانه‌اش در پله‌ها بگریزد و از این بابت خوشحال بود، چون کرایه‌اش را بدهکار بود و علاوه بر آن، به او مقروض هم بود."),
            StoryParagraph("It was not that he was so poor and crushed that he was ashamed of his position; on the contrary, he had lately been in an irritable, tense state of mind resembling hypochondria.", "نه اینکه آنقدر فقیر و خوار باشد که از وضعیتش خجالت بکشد؛ برعکس، اخیراً در حالتی تحریک‌پذیر و پرتنش شبیه به مالیخولیا به سر می‌برد."),
            StoryParagraph("He had become so completely absorbed in himself, and isolated from his fellows, that he dreaded meeting, not only his landlady, but anyone at all.", "آنقدر در خودش غرق شده و از همنوعانش جدا شده بود که از ملاقات با هر کسی می‌ترسید، نه فقط با صاحب‌خانه‌اش."),
            StoryParagraph("His name was Raskolnikov, and he was a student who had been compelled to abandon his studies because he could no longer pay for them.", "نامش راسکولنیکوف بود و دانشجویی بود که مجبور شده بود تحصیلش را رها کند چون دیگر نمی‌توانست هزینه‌اش را بپردازد."),
            StoryParagraph("He was a young man of remarkable intelligence, and this intelligence was both his gift and his curse, for it allowed him to see clearly the injustice of the world without giving him the means to correct it.", "او جوانی با هوشی چشمگیر بود و این هوش هم موهبتش بود و هم نفرینش، چون به او اجازه می‌داد بی‌عدالتی دنیا را با وضوح ببیند بی‌آنکه ابزاری برای اصلاحش به او بدهد."),
            StoryParagraph("He was dressed so poorly that any man of ordinary sensibility would have been ashamed to appear in the street in such rags, and yet he walked with the bearing of a man who had once known better days.", "آنقدر ژولیده لباس پوشیده بود که هر مردی با حساسیت معمولی از ظاهر شدن در خیابان با چنین جامه‌های پاره‌ای خجالت می‌کشید و با این حال با وقار مردی راه می‌رفت که روزهای بهتری را می‌شناخته بود."),
            StoryParagraph("His plan, of which he had been thinking for a month, was taking shape in his mind, and the shape it took was terrible.", "نقشه‌اش که یک ماه به آن فکر کرده بود، در ذهنش شکل می‌گرفت و شکلی که می‌گرفت هولناک بود."),
            StoryParagraph("There was an old woman, a pawnbroker, named Alyona Ivanovna, who lived in a small apartment in the same district.", "پیرزنی رباخوار به نام آلیونا ایوانوونا بود که در آپارتمانی کوچک در همان محله زندگی می‌کرد."),
            StoryParagraph("She was a petty tyrant who preyed on the poor and the desperate, lending money at usurious rates and treating her clients with contempt.", "او مستبدی کوچک بود که بر فقیران و درماندگان شکار می‌کرد، با نرخ‌های ربوی وامی می‌داد و با مشتریانش با تحقیر رفتار می‌کرد."),
            StoryParagraph("Raskolnikov had been to see her on several occasions, pawning small items to obtain money for food, and each time he had come away humiliated and enraged.", "راسکولنیکوف چند بار به دیدنش رفته بود، چیزهای کوچکی را برای گرفتن پول برای غذا گرو گذاشته بود و هر بار خوار و خشمگین بازگشته بود."),
            StoryParagraph("But now the thought of the old woman had begun to obsess him, and it was no longer a thought of mere contempt; it was a thought of something far more terrible.", "اما حالا فکر آن پیرزن شروع کرده بود به تسخیر او و دیگر فقط فکری از تحقیر نبود؛ فکری از چیزی بسیار هولناک‌تر بود."),
            StoryParagraph("He had conceived the idea that he might, by destroying a worthless and harmful life, obtain the means to do good, and that the destruction of one such creature would be justified by the good it made possible.", "ایده‌ای به ذهنش رسیده بود که ممکن است با نابود کردن زندگی‌ای بی‌ارزش و زیان‌آور، ابزاری برای انجام خوبی به دست آورد و نابودی یکی از این موجودات، با خوبی‌ای که ممکن می‌سازد توجیه شود."),
            StoryParagraph("This idea, dressed in the language of morality and philosophy, was in truth a rationalization of the darkest impulse of the human heart.", "این ایده که در زبان اخلاق و فلسفه پیچیده شده بود، در حقیقت توجیه‌سازی تاریک‌ترین انگیزه قلب انسان بود."),
            StoryParagraph("Raskolnikov, walking through the fetid streets of the city, was not thinking clearly, and he knew he was not thinking clearly, and yet he could not stop thinking.", "راسکولنیکوف، در حال قدم زدن در خیابان‌های گندیده شهر، با وضوح فکر نمی‌کرد و می‌دانست که با وضوح فکر نمی‌کند و با این حال نمی‌توانست از فکر کردن باز ایستد."),
            StoryParagraph("He had convinced himself, through hours of argument with himself, that the deed was not a crime but an act of justice, a small exception to a rule that had been made for lesser men.", "او خودش را با ساعت‌ها بحث با خودش قانع کرده بود که آن عمل جنایت نیست بلکه اقدامی عادلانه است، استثنایی کوچک بر قاعده‌ای که برای مردان کوچک‌تر ساخته شده بود."),
            StoryParagraph("He had convinced himself that he was a superior man, one of those few whose actions transcended the ordinary moral law, and who therefore had the right to act as others did not.", "او خودش را قانع کرده بود که مردی برتر است، یکی از آن عده معدود که اعمالشان از قانون اخلاقی معمول فراتر می‌رود و بنابراین حق دارند آنچنان عمل کنند که دیگران نمی‌کنند."),
            StoryParagraph("This was, of course, a lie, and the deepest part of him knew it was a lie, but he had buried that part of himself so deeply that he could no longer hear it.", "این البته دروغ بود و عمیق‌ترین بخش وجودش می‌دانست دروغ است، اما آن بخش از خودش را چنان عمیق دفن کرده بود که دیگر نمی‌توانست صدایش را بشنود."),
            StoryParagraph("He had even written an article, some months before, in which he had argued that extraordinary men had the right to commit crimes if those crimes served a higher purpose.", "حتی مقاله‌ای نوشته بود، چند ماه پیش، که در آن استدلال کرده بود مردان استثنایی حق دارند جنایت کنند اگر آن جنایات هدفی والاتر را خدمت کنند."),
            StoryParagraph("The article had been published, and he had been rather proud of it, though he had not yet had the courage to act upon its conclusions.", "مقاله منتشر شده بود و او به آن نسبتاً افتخار می‌کرد، هرچند هنوز جرات نکرده بود بر اساس نتیجه‌گیری‌هایش عمل کند."),
            StoryParagraph("And so he proceeded to the old woman's apartment, with an axe concealed in his coat, and there, in a scene of unspeakable violence, he accomplished the deed he had so long planned.", "و اینگونه به آپارتمان پیرزن رفت، با تبری که در کتش پنهان بود و آنجا، در صحنه‌ای از خشونت غیرقابل بیان، عملی که این همه مدت نقشه‌اش را کشیده بود انجام داد."),
            StoryParagraph("But the horror was not what he had expected; it was not the horror of the act but the horror that followed, and in that horror, he discovered that he had destroyed not only his victim but himself.", "اما وحشت آن چیزی نبود که انتظار داشت؛ وحشت نه از خود عمل بود بلکه از آنچه در پی آمد، و در آن وحشت کشف کرد که نه فقط قربانی‌اش بلکه خودش را نیز نابود کرده بود."),
            StoryParagraph("Worse still, the old woman's sister, Lizaveta, had returned home unexpectedly, and Raskolnikov had been forced to kill her too — a woman who had never harmed anyone, a woman who was, by all accounts, gentle and simple and kind.", "بدتر از آن، خواهر پیرزن، لیزاوتا، به‌طور غیرمنتظره به خانه بازگشته بود و راسکولنیکوف مجبور شده بود او را هم بکشد — زنی که هرگز به کسی آسیب نرسانده بود، زنی که به گفته همه، ملایم و ساده و مهربان بود."),
            StoryParagraph("This second murder, which he had not planned, would haunt him more than the first, for it was proof, if proof were needed, that his theory had been a lie.", "این قتل دوم، که نقشه‌اش را نکشیده بود، بیشتر از اولی تسخیرش می‌کرد، چون ثابت می‌کرد، اگر ثبوتی لازم بود، که نظریه‌اش دروغ بوده است."),
            StoryParagraph("For the rest of his life, Raskolnikov would be haunted by what he had done, and the haunting would take the form not of guilt alone but of something more terrible — the form of a question that had no answer.", "تا آخر عمرش، راسکولنیکوف توسط آنچه کرده بود تسخیر می‌شد و این تسخیر نه فقط به شکل گناه بلکه به شکل چیزی هولناک‌تر ظاهر می‌شد — به شکل پرسشی که پاسخی نداشت."),
            StoryParagraph("The question was this: had he been right? Had he, in fact, been one of those superior men for whom the rules do not apply?", "پرسش این بود: آیا حق داشته؟ آیا او در واقع یکی از آن مردان برتر بود که قواعد برایشان اعمال نمی‌شود؟"),
            StoryParagraph("Or had he been, all along, a mere criminal, a man who had destroyed another human being for no reason except that he wanted to, and had then constructed an elaborate theory to excuse himself?", "یا از همان ابتدا جنایتکاری ساده بود، مردی که انسانی دیگر را نابود کرده بود نه برای هیچ دلیلی جز اینکه می‌خواست و بعد نظریه‌ای پیچیده ساخته بود تا خودش را تبرئه کند؟"),
            StoryParagraph("This question, and the terrible uncertainty that accompanied it, was the punishment that Raskolnikov had brought upon himself — not the punishment of the law, but the punishment of the soul.", "این پرسش و عدم قطعیت هولناکی که همراهش بود، مجازاتی بود که راسکولنیکوف بر خودش آورده بود — نه مجازات قانون، بلکه مجازات روح.")
        )
    )

    // ─────────── فصل ۲: اعتراف ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Confession", titlePersian = "اعتراف",
        paragraphs = listOf(
            StoryParagraph("In the days that followed the murder, Raskolnikov wandered through the streets of Petersburg in a state of delirium, unable to eat, unable to sleep, unable to face the sound of his own thoughts.", "در روزهای پس از قتل، راسکولنیکوف در حالتی از هذیان در خیابان‌های پترزبورگ سرگردان بود، نه می‌توانست بخورد، نه بخوابد، نه با صدای افکار خودش روبرو شود."),
            StoryParagraph("He had, to his own astonishment, escaped detection; the police had arrested another man, a harmless peasant, and the case had been closed.", "به حیرت خودش، از کشف شدن گریخته بود؛ پلیس مرد دیگری را دستگیر کرده بود، دهقانی بی‌آزار و پرونده بسته شده بود."),
            StoryParagraph("But this escape brought him no peace; on the contrary, it intensified his torment, for it proved to him that the world was not just, and that innocence could be punished as readily as guilt.", "اما این فرار برایش هیچ آرامشی نیاورد؛ برعکس، شکنجه‌اش را تشدید کرد، چون به او ثابت کرد که دنیا عادل نیست و بی‌گناهی به همان راحتی می‌تواند مجازات شود که گناه."),
            StoryParagraph("He met, during this period, a man named Marmeladov, a former official who had drunk himself into ruin, and through Marmeladov he came to know the man's daughter, Sonia.", "در این دوره، با مردی به نام مارملادوف آشنا شد، کارمند سابقی که خودش را به ورطه مستی انداخته بود و از طریق مارملادوف با دختر آن مرد، سونیا، آشنا شد."),
            StoryParagraph("Marmeladov was a man who had once been respectable, a man who had once been capable of dignity, but who had fallen so far into degradation that he could no longer look at himself without hatred.", "مارملادوف مردی بود که زمانی محترم بود، مردی که زمانی قادر به وقار بود، اما چنان در انحطاط فروافتاده بود که دیگر نمی‌توانست بدون نفرت به خودش نگاه کند."),
            StoryParagraph("He told Raskolnikov the story of his family: of his wife, Katerina Ivanovna, a woman of noble birth reduced to poverty and illness; of his children, who went hungry every day; of his daughter Sonia, who had sacrificed herself to save them all.", "او داستان خانواده‌اش را برای راسکولنیکوف تعریف کرد: از همسرش، کاترینا ایوانوونا، زنی اصیل که به فقر و بیماری فروکاسته شده بود؛ از فرزندانش که هر روز گرسنه می‌ماندند؛ از دخترش سونیا که خودش را فدا کرده بود تا همه را نجات دهد."),
            StoryParagraph("Sonia was a prostitute, forced into that life to support her starving family, and yet she was, in a paradox that Raskolnikov could not understand, the purest soul he had ever met.", "سونیا روسپی بود، به آن زندگی رانده شده تا خانواده گرسنه‌اش را سیر کند و با این حال، در تناقضی که راسکولنیکوف نمی‌توانست بفهمد، پاک‌ترین روحی بود که تا حالا دیده بود."),
            StoryParagraph("She bore her degradation without complaint, and she loved her family without reservation, and she trusted in God without doubt.", "تحقیرش را بدون شکایت تحمل می‌کرد و خانواده‌اش را بدون قید و شرط دوست داشت و بدون شک به خدا اعتماد داشت."),
            StoryParagraph("Raskolnikov, who had long since abandoned any faith, found himself drawn to Sonia not despite her faith but because of it, for her faith was the one thing in his world that he could not explain away.", "راسکولنیکوف که مدتها پیش هر ایمانی را رها کرده بود، به سمت سونیا کشیده شد نه به رغم ایمانش، بلکه به دلیل آن، چون ایمان او تنها چیزی در دنیایش بود که نمی‌توانست توضیحش دهد."),
            StoryParagraph("He came to her, eventually, to confess, not because he wanted forgiveness — he did not believe in forgiveness — but because he could no longer bear the solitude of his secret.", "در نهایت، به سراغش آمد تا اعتراف کند، نه چون طلب بخشش داشت — به بخشش باور نداشت — بلکه چون دیگر نمی‌توانست تنهایی رازش را تحمل کند."),
            StoryParagraph("'I killed the old pawnbroker and her sister,' he said, in a voice that was almost a whisper, and he waited for her to recoil in horror.", "گفت: «پیرزن رباخوار و خواهرش را کشتم.» با صدایی که تقریباً زمزمه بود و منتظر ماند تا از وحشت عقب بکشد."),
            StoryParagraph("But Sonia did not recoil; she wept, and she embraced him, and she said, 'There is no one in the whole world now more unhappy than you are.'", "اما سونیا عقب نکشید؛ گریست و او را در آغوش گرفت و گفت: «حالا در تمام دنیا هیچ‌کس بدبخت‌تر از تو نیست.»"),
            StoryParagraph("This response, which Raskolnikov had neither expected nor deserved, broke something in him, and for the first time since the murder, he allowed himself to weep.", "این پاسخ که راسکولنیکوف نه انتظارش را داشت و نه سزاوارش بود، چیزی در او شکست و برای اولین بار پس از قتل، به خودش اجازه داد گریه کند."),
            StoryParagraph("'What have I done?' he cried. 'What have I done to myself?'", "فریاد زد: «چه کرده‌ام؟ با خودم چه کرده‌ام؟»"),
            StoryParagraph("Sonia, who had no answers, offered him the only thing she had: herself, her tears, her presence, her faith that even the worst sinner could be redeemed.", "سونیا که پاسخی نداشت، تنها چیزی را که داشت به او عرضه کرد: خودش، اشک‌هایش، حضورش، ایمانش به اینکه حتی بدترین گناهکار می‌تواند رستگار شود."),
            StoryParagraph("'You must go to the crossroads,' she said, 'and kiss the earth that you have defiled, and bow to all four corners of the world, and say aloud to all men: I am a murderer.'", "گفت: «باید به چهارراه بروی و زمینی را که آلوده کرده‌ای ببوسی و به چهار گوشه دنیا تعظیم کنی و با صدای بلند به همه مردمان بگویی: من قاتلم.»"),
            StoryParagraph("Raskolnikov did not immediately obey, but the seed that Sonia had planted in him began, slowly, to grow.", "راسکولنیکوف بلافاصله اطاعت نکرد، اما بذری که سونیا در او کاشته بود به‌آرامی شروع کرد به رشد."),
            StoryParagraph("He began to see that his crime had not been the act of a superior man but the act of a desperate one, a man who had been crushed by poverty and humiliation until he could no longer think clearly.", "شروع کرد به دیدن اینکه جنایتش نه عمل مردی برتر بلکه عمل مردی درمانده بود، مردی که توسط فقر و تحقیر چنان خرد شده بود که دیگر نمی‌توانست واضح فکر کند."),
            StoryParagraph("He began to see that the theory he had constructed, the theory of the superior man, was not a justification but a symptom — the symptom of a mind that had lost its moral bearings.", "شروع کرد به دیدن اینکه نظریه‌ای که ساخته بود، نظریه مرد برتر، نه توجیه بلکه نشانه‌ای بود — نشانه ذهنی که جهت‌یابی اخلاقی‌اش را از دست داده بود."),
            StoryParagraph("And he began to see, most terribly of all, that he had destroyed not only two women but himself — that he had committed a crime against his own soul from which he might never recover.", "و شروع کرد به دیدن، هولناک‌ترین همه، که نه فقط دو زن بلکه خودش را نابود کرده بود — که جنایتی علیه روح خودش مرتکب شده بود که ممکن بود هرگز از آن بهبود نیابد."),
            StoryParagraph("This was the beginning of his redemption, though he did not know it yet; for redemption, in Dostoevsky's vision, does not come through the intellect but through the heart.", "این آغاز رستگاری‌اش بود، هرچند هنوز نمی‌دانست؛ چون رستگاری، در بینش داستایفسکی، از طریق عقل نمی‌آید بلکه از طریق قلب."),
            StoryParagraph("And so he went to the police station, and there, with trembling voice and burning cheeks, he confessed to the crime that had been consuming him.", "و اینگونه به کلانتری رفت و آنجا، با صدای لرزان و گونه‌های سوزان، به جنایتی که او را می‌خورد اعتراف کرد."),
            StoryParagraph("The officer who took his confession did not understand at first; he thought Raskolnikov was mad, or drunk, or both.", "افسری که اعترافش را گرفت ابتدا نفهمید؛ فکر کرد راسکولنیکوف دیوانه است، یا مست، یا هر دو."),
            StoryParagraph("But when the full weight of the confession became clear, the officer, who had seen much in his years of service, found himself oddly moved.", "اما وقتی وزن کامل اعتراف روشن شد، آن افسر که در سال‌های خدمتش چیزهای زیادی دیده بود، به شکلی عجیب متأثر شد."),
            StoryParagraph("'You are a strange man,' he said. 'You could have escaped. You had no need to confess.'", "گفت: «تو مرد عجیبی هستی. می‌توانستی فرار کنی. نیازی به اعتراف نداشتی.»"),
            StoryParagraph("'That,' said Raskolnikov, 'is precisely why I had to.'", "راسکولنیکوف گفت: «دقیقاً به همین دلیل مجبور بودم.»"),
            StoryParagraph("And with those words, he began, at last, the long and terrible journey toward redemption — a journey that would lead him not to freedom but to Siberia, and not to ease but to a suffering that would purify.", "و با آن کلمات، در نهایت، سفر طولانی و هولناک به سوی رستگاری را آغاز کرد — سفری که او را نه به آزادی بلکه به سیبری می‌برد و نه به آسودگی بلکه به رنجی که پاک می‌کند.")
        )
    )

    // ─────────── فصل ۳: سونیا ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Sonia", titlePersian = "سونیا",
        paragraphs = listOf(
            StoryParagraph("Sonia Marmeladov was, in many ways, the most improbable heroine in all of literature: a prostitute, a woman of the streets, who was nevertheless the purest and most Christ-like figure in the novel.", "سونیا مارملادوف، از بسیاری جهات، نامحتمل‌ترین قهرمان تمام ادبیات بود: روسپی، زنی از خیابان، که با این حال پاک‌ترین و مسیح‌گونه‌ترین چهره رمان بود."),
            StoryParagraph("She had been forced into her profession by circumstances beyond her control, by a stepmother who was cruel, by a father who was weak, by a poverty that left no other option.", "او به حرفه‌اش توسط شرایطی فراتر از کنترلش رانده شده بود، توسط نامادری‌ای که بی‌رحم بود، توسط پدری که ضعیف بود، توسط فقری که هیچ گزینه دیگری باقی نمی‌گذاشت."),
            StoryParagraph("But she had not allowed her circumstances to define her soul; she had, in the midst of degradation, preserved a purity that those who judged her could not even imagine.", "اما اجازه نداده بود شرایطش روحش را تعریف کند؛ در میان تحقیر، پاکی‌ای حفظ کرده بود که کسانی که قضاوتش می‌کردند حتی نمی‌توانستند تصورش کنند."),
            StoryParagraph("She loved her family with a fierce and selfless love, sacrificing herself daily so that her younger siblings might eat, so that her father might drink himself into a brief oblivion.", "خانواده‌اش را با عشقی سخت و بی‌خود دوست داشت، هر روز خودش را فدا می‌کرد تا خواهر و برادرهای کوچک‌ترش غذا بخورند، تا پدرش خودش را به فراموشی کوتاهی بنوشاند."),
            StoryParagraph("She loved God with a simple and unwavering faith, believing that even the lowest sinner could be forgiven, that even the darkest night would eventually give way to dawn.", "خدا را با ایمانی ساده و تزلزل‌ناپذیر دوست داشت، باور داشت که حتی پست‌ترین گناهکار می‌تواند بخشیده شود، که حتی تاریک‌ترین شب در نهایت جای خود را به سپیده می‌دهد."),
            StoryParagraph("And she loved Raskolnikov, not because he deserved it, but because love does not ask whether it is deserved; it loves because it must.", "و راسکولنیکوف را دوست داشت، نه چون سزاوارش بود، بلکه چون عشق نمی‌پرسد که آیا سزاوار است؛ عشق می‌ورزد چون باید."),
            StoryParagraph("It was this love, this unreasonable, irrational, absolutely unconditional love, that saved Raskolnikov, and that has made Sonia one of the most beloved characters in Russian literature.", "این عشق بود، این عشق غیرمنطقی، غیرعقلانی، کاملاً بی‌قید و شرط، که راسکولنیکوف را نجات داد و سونیا را یکی از محبوب‌ترین شخصیت‌های ادبیات روسی کرده است."),
            StoryParagraph("For Raskolnikov's sin had been, in essence, a sin against love — against the possibility of love, against the reality of love, against the God who is love.", "چون گناه راسکولنیکوف در جوهر، گناهی علیه عشق بود — علیه امکان عشق، علیه واقعیت عشق، علیه خدایی که عشق است."),
            StoryParagraph("And it was only through love, through Sonia's love and through his own halting, imperfect acceptance of that love, that he could be healed.", "و تنها از طریق عشق بود، از طریق عشق سونیا و از طریق پذیرش لرزان و ناقص خودش از آن عشق، که می‌توانست شفا یابد."),
            StoryParagraph("This was Dostoevsky's deepest conviction: that the human soul cannot be healed by reason alone, that the intellect is not sufficient to cure what the intellect has wounded.", "این عمیق‌ترین باور داستایفسکی بود: روح انسان را نمی‌توان تنها با عقل شفا داد، عقل کافی نیست برای درمان آنچه عقل زخمی کرده."),
            StoryParagraph("The intellect can construct theories, can justify actions, can rationalize crimes; but it cannot love, and therefore it cannot save.", "عقل می‌تواند نظریه بسازد، اعمال را توجیه کند، جنایات را منطقی کند؛ اما نمی‌تواند عشق بورزد و بنابراین نمی‌تواند نجات دهد."),
            StoryParagraph("Only love can save, and love is not a matter of the intellect but of the whole person — of the body, of the heart, of the soul, of everything that reason cannot touch.", "تنها عشق می‌تواند نجات دهد و عشق امری عقلی نیست بلکه امری مربوط به تمام شخص است — بدن، قلب، روح، هر چیزی که عقل نمی‌تواند لمس کند."),
            StoryParagraph("Sonia was not intelligent in the way that Raskolnikov was intelligent, and she could not follow his arguments, and she did not understand his theories.", "سونیا به آن شیوه‌ای که راسکولنیکوف باهوش بود باهوش نبود، نمی‌توانست استدلال‌هایش را دنبال کند و نظریه‌هایش را نمی‌فهمید."),
            StoryParagraph("But she understood something more important: she understood that he was suffering, and she understood that suffering must be answered not with argument but with presence.", "اما چیزی مهم‌تر می‌فهمید: می‌فهمید که او رنج می‌برد و می‌فهمید که به رنج باید نه با استدلال، بلکه با حضور پاسخ داد."),
            StoryParagraph("And so she was present with him, in his suffering, and she did not try to explain it away or to make it bearable; she simply suffered with him, and in suffering with him, she began to heal him.", "و اینگونه با او در رنجش حاضر بود و تلاش نکرد توضیحش دهد یا تحمل‌پذیرش کند؛ فقط با او رنج کشید و در رنج کشیدن با او، شروع کرد به شفا دادنش."),
            StoryParagraph("She read to him from the Gospel, the story of Lazarus, and her voice trembled with a faith that Raskolnikov could not share but could not entirely dismiss.", "برای او از انجیل خواند، داستان لازاروس، و صدایش از ایمانی می‌لرزید که راسکولنیکوف نمی‌توانست شریکش شود اما نمی‌توانست کاملاً ردش کند."),
            StoryParagraph("'He who believes in me,' she read, 'though he were dead, yet shall he live.'", "خواند: «آن که به من ایمان آورد، حتی اگر مرده باشد، زنده خواهد شد.»"),
            StoryParagraph("Raskolnikov listened, and something in him stirred — not faith, not yet, but the possibility of faith, the opening of a door that had long been sealed.", "راسکولنیکوف گوش داد و چیزی در او تکان خورد — نه ایمان، نه هنوز، بلکه امکان ایمان، گشایش دری که مدت‌ها مهر و موم شده بود."),
            StoryParagraph("This is the deepest mystery of Dostoevsky's Christianity: that God is not found in arguments but in shared suffering, that Christ is present not in the doctrine but in the embrace.", "این عمیق‌ترین رمز مسیحیت داستایفسکی است: خدا در استدلال‌ها یافت نمی‌شود بلکه در رنج مشترک، مسیح نه در عقیده بلکه در آغوش حاضر است."),
            StoryParagraph("Sonia embodied this mystery in her very being, and her presence in the novel is the presence of grace in a world of law, of hope in a world of despair, of life in a world of death.", "سونیا این رمز را در خودِ وجودش مجسم می‌کرد و حضورش در رمان، حضور فیض در دنیای قانون، امید در دنیای ناامیدی، زندگی در دنیای مرگ است."),
            StoryParagraph("She was not perfect — Dostoevsky never makes his saints perfect — and she had her own struggles, her own doubts, her own moments of despair.", "بی‌عیب نبود — داستایفسکی هیچ‌وقت قدیسانش را بی‌عیب نمی‌سازد — و خودش هم سختی‌هایش را داشت، شک‌هایش، لحظات ناامیدی‌اش."),
            StoryParagraph("But she continued to believe, continued to love, continued to hope, and in that continued belief and love and hope, she became the instrument of Raskolnikov's salvation.", "اما همچنان باور می‌کرد، همچنان عشق می‌ورزید، همچنان امید داشت و در آن باور و عشق و امید ادامه‌دار، ابزار نجات راسکولنیکوف شد."),
            StoryParagraph("At the end of the novel, Raskolnikov, having confessed and been sentenced to Siberia, is visited by Sonia, who has followed him there, and in her presence he begins, at last, to love.", "در پایان رمان، راسکولنیکوف که اعتراف کرده و به سیبری محکوم شده، توسط سونیا ملاقات می‌شود که به آنجا دنبالش رفته و در حضور او، بالاخره، شروع به عشق ورزیدن می‌کند."),
            StoryParagraph("'Love had resurrected them,' Dostoevsky writes, and in that simple sentence, he encapsulates the entire message of the novel: that love is the only force capable of resurrecting the dead soul.", "داستایفسکی می‌نویسد: «عشق آنها را دوباره زنده کرده بود» و در آن جمله ساده، تمام پیام رمان را خلاصه می‌کند: عشق تنها نیرویی است که قادر به زنده کردن روح مرده است."),
            StoryParagraph("Raskolnikov had to go through hell to learn this, and Sonia had to descend into hell to teach it, but in the end, the lesson was learned, and the novel ends not with despair but with hope.", "راسکولنیکوف باید از جهنم می‌گذشت تا این را یاد بگیرد و سونیا باید به جهنم نزول می‌کرد تا این را بیاموزد، اما در نهایت درس آموخته شد و رمان نه با ناامیدی بلکه با امید پایان می‌یابد."),
            StoryParagraph("This is the great and terrible beauty of Dostoevsky: that he shows us the depths to which the human soul can sink, and then shows us that even from those depths, there is a way back.", "این زیبایی بزرگ و هولناک داستایفسکی است: او اعماق فرورفتن روح انسان را به ما نشان می‌دهد و بعد نشان می‌دهد که حتی از آن اعماق، راهی برای بازگشت وجود دارد."),
            StoryParagraph("And the way back, always and everywhere, is love.", "و راه بازگشت، همیشه و همه‌جا، عشق است.")
        )
    )

    // ─────────── فصل ۴: پورفیری ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Porfiry", titlePersian = "پورفیری",
        paragraphs = listOf(
            StoryParagraph("The investigator Porfiry Petrovich was the most dangerous adversary Raskolnikov faced, more dangerous than the police, more dangerous than his own conscience, because Porfiry understood the criminal mind.", "بازپرس پورفیری پتروویچ خطرناک‌ترین دشمنی بود که راسکولنیکوف با آن روبرو شد، خطرناک‌تر از پلیس، خطرناک‌تر از وجدان خودش، چون پورفیری ذهن جنایتکار را می‌فهمید."),
            StoryParagraph("He was a man of middle age, with a round face and a manner that was almost comically mild, and yet there was something in his eyes that made Raskolnikov uneasy from their very first meeting.", "او مردی میان‌سال بود، با صورتی گرد و رفتاری که تقریباً به شکلی کمیک ملایم بود و با این حال چیزی در چشمانش بود که راسکولنیکوف را از همان اولین ملاقات ناراحت می‌کرد."),
            StoryParagraph("Porfiry did not arrest Raskolnikov, did not accuse him, did not even openly suspect him — or rather, he pretended not to suspect him, while making it perfectly clear that he suspected everything.", "پورفیری راسکولنیکوف را دستگیر نکرد، متهمش نکرد، حتی آشکارا مشکوکش نشد — یا بهتر بگوییم، تظاهر کرد که مشکوکش نیست، در حالی که کاملاً روشن می‌کرد که به همه چیز مشکوک است."),
            StoryParagraph("His method was psychological, not legal; he did not try to prove Raskolnikov's guilt with evidence, but to make Raskolnikov prove it himself, with his own words and his own behavior.", "روشش روانشناختی بود، نه حقوقی؛ تلاش نکرد گناه راسکولنیکوف را با مدرک ثابت کند، بلکه راسکولنیکوف را وادار کرد خودش آن را ثابت کند، با کلمات و رفتار خودش."),
            StoryParagraph("He engaged Raskolnikov in long, rambling conversations, full of apparent irrelevancies and hidden significances, and he watched, with the patience of a cat watching a mouse, as Raskolnikov's composure slowly crumbled.", "راسکولنیکوف را به گفتگوهای طولانی و پراکنده مشغول می‌کرد، پر از بی‌ربط‌های ظاهری و دلالت‌های پنهان و تماشا می‌کرد، با صبر گربه‌ای که موش را تماشا می‌کند، که چگونه خونسردی راسکولنیکوف به‌آرامی فرو می‌ریزد."),
            StoryParagraph("He spoke of trivial matters — of the weather, of literature, of the latest gossip — but every triviality was a trap, and every trap was designed to make Raskolnikov reveal himself.", "از مسائل پیش‌پاافتاده صحبت می‌کرد — از هوا، از ادبیات، از آخرین شایعات — اما هر پیش‌پاافتادگی تله‌ای بود و هر تله طراحی شده بود تا راسکولنیکوف خودش را آشکار کند."),
            StoryParagraph("'I know you killed the old woman,' Porfiry said at last, in one of their final interviews, and the words were not an accusation but a statement of fact.", "پورفیری در نهایت، در یکی از آخرین ملاقات‌هایشان، گفت: «می‌دانم پیرزن را کشتی.» و آن کلمات اتهام نبودند بلکه بیان واقعیت بودند."),
            StoryParagraph("Raskolnikov denied it, as he had denied everything, but the denial was hollow, and both men knew it was hollow, and in that shared knowledge there was a kind of terrible intimacy.", "راسکولنیکوف انکار کرد، همانطور که همه چیز را انکار کرده بود، اما انکار توخالی بود و هر دو مرد می‌دانستند توخالی است و در آن دانستن مشترک نوعی صمیمیت هولناک بود."),
            StoryParagraph("Porfiry did not arrest him then, though he could have; he let him go, because he wanted Raskolnikov to confess, not to be captured.", "پورفیری آن موقع دستگیرش نکرد، هرچند می‌توانست؛ رهایش کرد، چون می‌خواست راسکولنیکوف اعتراف کند، نه دستگیر شود."),
            StoryParagraph("'Go,' Porfiry said, 'and confess. It will be better for you. The suffering will be less than the hiding.'", "پورفیری گفت: «برو و اعتراف کن. برایت بهتر خواهد بود. رنج کمتر از پنهان شدن خواهد بود.»"),
            StoryParagraph("And Raskolnikov, who had not expected such advice from an investigator, found himself oddly moved by it.", "و راسکولنیکوف که از یک بازپرس چنین توصیه‌ای انتظار نداشت، به شکلی عجیب از آن متأثر شد."),
            StoryParagraph("Porfiry was not a villain, in the conventional sense; he was a man of the law, and he believed in the law, but he also believed in the soul, and he knew that the soul of a criminal could only be healed by confession.", "پورفیری به معنای متعارف شرور نبود؛ مردی از قانون بود و به قانون باور داشت، اما به روح هم باور داشت و می‌دانست که روح یک جنایتکار تنها با اعتراف شفا می‌یابد."),
            StoryParagraph("He was, in a way, the instrument of grace in the novel, the human agent through whom the divine mercy was mediated, the stern but ultimately loving father who must let the child fall in order to teach him to stand.", "او به نوعی، ابزار فیض در رمان بود، عامل انسانی‌ای که رحمت الهی از طریقش منتقل می‌شد، پدر سختگیر اما در نهایت مهربانی که باید بگذارد فرزند بیفتد تا ایستادن را بیاموزد."),
            StoryParagraph("His wisdom was not the wisdom of the intellect, though he was intelligent; it was the wisdom of experience, of having seen too many criminals to believe in the simplicity of crime.", "حکمتش حکمت عقل نبود، هرچند باهوش بود؛ حکمت تجربه بود، از اینکه جنایتکاران بیش از حد دیده بود که به سادگی جنایت باور کند."),
            StoryParagraph("He knew that every crime was a tragedy, and that every criminal was, in some sense, a victim — a victim of circumstance, of society, of his own weaknesses and illusions.", "می‌دانست که هر جنایتی تراژدی است و هر جنایتکاری به نوعی قربانی است — قربانی شرایط، جامعه، ضعف‌ها و توهمات خودش."),
            StoryParagraph("This knowledge did not make him soft, as some accused him of being; it made him patient, and patience was the most terrible weapon he wielded.", "این دانش او را نرم نکرد، همانطور که برخی متهمش می‌کردند؛ صبورش کرد و صبر هولناک‌ترین سلاحی بود که به کار می‌برد."),
            StoryParagraph("He could wait, as no one else could wait, and in waiting, he could see the truth emerge, slowly and inevitably, from the depths of the guilty soul.", "می‌توانست منتظر بماند، همانطور که هیچ‌کس دیگری نمی‌توانست و در انتظار، می‌توانست حقیقت را ببیند که به‌آرامی و اجتناب‌ناپذیر از اعماق روح گناهکار بیرون می‌آید."),
            StoryParagraph("'I have been expecting you,' he would say, each time Raskolnikov came to him, and the words, which seemed casual, were in fact a sword, cutting through every pretense.", "می‌گفت: «منتظرت بودم.» هر بار که راسکولنیکوف نزدش می‌آمد و آن کلمات که به نظر معمولی می‌رسیدند، در واقع شمشیری بودند که هر تظاهری را می‌دریدند."),
            StoryParagraph("In the end, it was Porfiry's quiet certainty, more than any threat of punishment, that broke Raskolnikov's resistance, and drove him to the police station to confess.", "در نهایت، اطمینان آرام پورفیری، بیش از هر تهدید مجازاتی، مقاومت راسکولنیکوف را شکست و او را به کلانتری کشاند تا اعتراف کند."),
            StoryParagraph("And Porfiry, who had done his duty, and who had also done something more than his duty, watched him go with a satisfaction that was not triumph but relief.", "و پورفیری که وظیفه‌اش را انجام داده بود و چیزی بیش از وظیفه‌اش هم انجام داده بود، رفتنش را با رضایتی تماشا کرد که نه پیروزی بلکه آسودگی بود."),
            StoryParagraph("He had not caught a criminal; he had saved a soul. And in Dostoevsky's vision, that was the highest achievement to which any man could aspire.", "او یک جنایتکار را نگرفته بود؛ روحی را نجات داده بود. و در بینش داستایفسکی، این بالاترین دستاوردی بود که هر انسانی می‌توانست برایش بکوشد.")
        )
    )

    // ─────────── فصل ۵: سیبری ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Siberia", titlePersian = "سیبری",
        paragraphs = listOf(
            StoryParagraph("Siberia, in the Russian imagination, is not merely a place; it is a state of the soul, a vast and frozen expanse where the exiled go to suffer and, sometimes, to be reborn.", "سیبری، در تصور روسی، فقط یک مکان نیست؛ حالتی از روح است، گستره‌ای عظیم و یخ‌زده که تبعیدیان به آنجا می‌روند تا رنج بکشند و گاهی دوباره متولد شوند."),
            StoryParagraph("Raskolnikov was sentenced to eight years of penal servitude, and he went to Siberia with the dull resignation of a man who had already suffered the worst that life could offer.", "راسکولنیکوف به هشت سال کار سخت محکوم شد و با تسلیم کسل‌کننده مردی که بدترین چیزی که زندگی می‌توانست ارائه دهد را قبلاً تجربه کرده بود به سیبری رفت."),
            StoryParagraph("The journey itself was a kind of purgatory: months of travel through endless plains and frozen forests, in the company of criminals of every description, under the indifferent eyes of guards.", "خود سفر نوعی برزخ بود: ماه‌ها سفر از میان دشت‌های بی‌پایان و جنگل‌های یخ‌زده، در همراهی جنایتکارانی از هر نوعی، زیر چشمان بی‌تفاوت نگهبانان."),
            StoryParagraph("Raskolnikov endured it all with a passivity that troubled even those who had no reason to care about him, for passivity in a man of his intelligence was more terrible than rage.", "راسکولنیکوف همه‌اش را با انفعالی تحمل کرد که حتی کسانی را که هیچ دلیلی برای اهمیت دادن به او نداشتند ناراحت می‌کرد، چون انفعال در مردی با هوش او، از خشم هولناک‌تر بود."),
            StoryParagraph("At the prison, he was assigned to the lowest caste of prisoners: those who were despised even by other criminals, those who had no friends, no allies, no hope.", "در زندان، به پست‌ترین طبقه زندانیان اختصاص یافت: کسانی که حتی توسط جنایتکاران دیگر تحقیر می‌شدند، کسانی که هیچ دوستی، هیچ متحدی، هیچ امیدی نداشتند."),
            StoryParagraph("The other prisoners hated him — not because of his crime, for many of them had committed worse, but because of his manner, his intelligence, his evident contempt for them.", "زندانیان دیگر از او متنفر بودند — نه به خاطر جنایتش، چون بسیاری از آنها بدتر کرده بودند، بلکه به خاطر رفتارش، هوشش، تحقیر آشکارش نسبت به آنها."),
            StoryParagraph("'You are a gentleman,' they said to him, with that peculiar mixture of irony and resentment that only the oppressed can summon, 'and you do not belong among us.'", "به او می‌گفتند: «تو یک نجیب‌زاده‌ای» با آن آمیزه عجیب طعنه و کینه که تنها ستمدیدگان می‌توانند فرا خوانند، «و به ما تعلق نداری.»"),
            StoryParagraph("And Raskolnikov, who had once believed himself superior to all men, found himself despised by the very men he had thought beneath him.", "و راسکولنیکوف، که زمانی خودش را برتر از همه مردان می‌پنداشت، خود را تحقیرشده توسط همان مردانی یافت که فکر می‌کرد زیر او هستند."),
            StoryParagraph("This was the deepest humiliation of his life — deeper even than the crime, deeper even than the confession — for it forced him to confront the emptiness of his own pride.", "این عمیق‌ترین تحقیر زندگی‌اش بود — عمیق‌تر حتی از جنایت، عمیق‌تر حتی از اعتراف — چون او را وادار کرد با پوچی غرور خودش روبرو شود."),
            StoryParagraph("Sonia had followed him to Siberia, as she had promised she would, and she settled in a small town near the prison, and she came to see him whenever she was permitted.", "سونیا به سیبری دنبالش آمده بود، همانطور که قول داده بود، و در شهر کوچکی نزدیک زندان ساکن شده بود و هر وقت اجازه داشت به دیدنش می‌آمد."),
            StoryParagraph("She did not speak to him of God, nor of redemption, nor of the future; she simply came, and she sat with him, and she waited.", "با او از خدا صحبت نمی‌کرد، نه از رستگاری، نه از آینده؛ فقط می‌آمد و کنارش می‌نشست و منتظر می‌ماند."),
            StoryParagraph("This waiting, this patient, silent, absolutely faithful waiting, was more powerful than any argument could have been, and slowly, imperceptibly, it began to work upon Raskolnikov's heart.", "این انتظار، این انتظار صبورانه، خاموش، کاملاً وفادار، از هر استدلالی قدرتمندتر بود و به‌آرامی، نامحسوس، شروع کرد به کار کردن بر قلب راسکولنیکوف."),
            StoryParagraph("He began to notice her, truly to notice her, not as a symbol of faith or a reminder of his guilt, but as a human being, flawed and suffering and infinitely precious.", "شروع کرد به دیدنش، واقعاً دیدنش، نه به عنوان نمادی از ایمان یا یادآوری گناهش، بلکه به عنوان انسانی، معیوب و رنجور و بی‌نهایت ارزشمند."),
            StoryParagraph("He began to see that she had sacrificed everything for him — her reputation, her comfort, her very life — and that she had done so not because she expected anything in return, but because she loved him.", "شروع کرد به دیدن اینکه او همه چیز را برایش فدا کرده بود — آبرویش، آسایشش، خودِ زندگی‌اش — و این کار را نه چون انتظار چیزی در عوض داشت، بلکه چون دوستش داشت."),
            StoryParagraph("And in seeing this, he began, at last, to love her in return — not with the passionate love of youth, but with the deep, slow, enduring love of one soul recognizing another.", "و در دیدن این، بالاخره، شروع کرد به دوست داشتن متقابلش — نه با عشق پرشور جوانی، بلکه با عشق عمیق، آهسته، پایدار یک روح که روح دیگری را می‌شناسد."),
            StoryParagraph("One day, as they sat together by the river, Raskolnikov threw himself at her feet, and he wept — wept as he had not wept since childhood, wept with a grief that was also a relief.", "یک روز، همانطور که کنار رودخانه با هم نشسته بودند، راسکولنیکوف خودش را به پای او انداخت و گریست — گریست همانطور که از کودکی نگریسته بود، گریست با اندوهی که آسودگی هم بود."),
            StoryParagraph("Sonia, astonished, drew back, but he held her, and he said, 'I love you,' and the words, which had once seemed to him the emptiest of all words, now seemed to him the only words worth speaking.", "سونیا حیرت‌زده عقب کشید، اما او نگهش داشت و گفت: «دوستت دارم» و آن کلمات که زمانی برایش پوچ‌ترین تمام کلمات به نظر می‌رسیدند، حالا برایش تنها کلماتی بودند که ارزش گفتن داشتند."),
            StoryParagraph("'You are the only one who has ever loved me,' he said, 'and you are the only one I have ever loved, and I did not know — I did not know what love was until now.'", "گفت: «تو تنها کسی هستی که تا حالا دوستم داشته و تو تنها کسی هستی که تا حالا دوستش داشته‌ام و نمی‌دانستم — نمی‌دانستم عشق چیست تا حالا.»"),
            StoryParagraph("And Sonia, who had waited for this moment for so long, who had trusted that it would come even when every sign pointed otherwise, wept with him, and her tears were tears of joy.", "و سونیا که این همه مدت منتظر این لحظه بود، که اعتماد داشت می‌آید حتی وقتی هر نشانه‌ای خلافش را می‌گفت، با او گریست و اشک‌هایش اشک شادی بودند."),
            StoryParagraph("This was the moment of Raskolnikov's true conversion — not the confession, not the sentence, not even the suffering of the prison, but this, the moment when he allowed himself to love and be loved.", "این لحظه تبدیل واقعی راسکولنیکوف بود — نه اعتراف، نه حکم، نه حتی رنج زندان، بلکه این، لحظه‌ای که به خودش اجازه داد دوست بدارد و دوست داشته شود."),
            StoryParagraph("For Dostoevsky, this was the deepest truth of the human condition: that we are not saved by our ideas, not by our achievements, not even by our suffering, but by love.", "برای داستایفسکی، این عمیق‌ترین حقیقت وضعیت انسانی بود: ما نه با ایده‌هایمان نجات می‌یابیم، نه با دستاوردهایمان، نه حتی با رنجمان، بلکه با عشق."),
            StoryParagraph("Raskolnikov had spent his entire life trying to prove that he was extraordinary, that he was above the common laws of morality, that he had the right to act as he pleased.", "راسکولنیکوف تمام عمرش را صرف تلاش کرده بود ثابت کند که استثنایی است، که برتر از قوانین متعارف اخلاق است، که حق دارد هر طور که می‌خواهد عمل کند."),
            StoryParagraph("And now, in the depths of Siberia, in the company of the most despised of men, in the arms of a former prostitute, he discovered that he was, after all, only human — and that being human was enough.", "و حالا، در اعماق سیبری، در همراهی تحقیرشده‌ترین مردان، در آغوش روسپی سابقی، کشف کرد که بعد از همه، فقط انسان بود — و اینکه انسان بودن کافی است."),
            StoryParagraph("'Love had resurrected them,' Dostoevsky writes at the end of the novel, and it is the simplest and the most profound sentence in all of literature.", "داستایفسکی در پایان رمان می‌نویسد: «عشق آنها را دوباره زنده کرده بود» و این ساده‌ترین و عمیق‌ترین جمله در تمام ادبیات است."),
            StoryParagraph("The novel that began with a murder ends with a resurrection; the story that began in darkness ends in light; the man who began as a criminal ends as a saint.", "رمانی که با قتلی آغاز شد با رستاخیزی پایان می‌یابد؛ داستانی که در تاریکی آغاز شد در روشنایی پایان می‌یابد؛ مردی که به عنوان جنایتکار آغاز شد به عنوان قدیس پایان می‌یابد."),
            StoryParagraph("This is the message of Dostoevsky, and the message of the Russian soul: that no one is beyond redemption, that no sin is unforgivable, that no night is so dark that dawn will not come.", "این پیام داستایفسکی است و پیام روح روسی: هیچ‌کس فراتر از رستگاری نیست، هیچ گناهی غیرقابل بخشش نیست، هیچ شبی آنقدر تاریک نیست که سپیده نیاید.")
        )
    )

    // ─────────── فصل ۶: پایان و مکافات ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Punishment and the Redemption", titlePersian = "مکافات و رستگاری",
        paragraphs = listOf(
            StoryParagraph("The word 'punishment' in the title of Dostoevsky's novel has a double meaning that is often lost in translation, for the Russian word 'nakazanie' carries both the sense of legal penalty and the sense of moral lesson.", "واژه «مکافات» در عنوان رمان داستایفسکی معنایی دوگانه دارد که اغلب در ترجمه از دست می‌رود، چون واژه روسی «ناکازانیه» هم معنای مجازات قانونی را حمل می‌کند و هم معنای درس اخلاقی."),
            StoryParagraph("Raskolnikov was punished in both senses: by the law, which sent him to Siberia, and by his own conscience, which tortured him more than any prison could.", "راسکولنیکوف به هر دو معنا مجازات شد: توسط قانون، که او را به سیبری فرستاد و توسط وجدان خودش، که بیش از هر زندانی شکنجه‌اش کرد."),
            StoryParagraph("But the punishment, in the end, was not the point; the punishment was the means by which the redemption was achieved, the fire through which the gold was purified.", "اما مکافات در نهایت نکته اصلی نبود؛ مکافات وسیله‌ای بود که رستگاری از طریقش به دست آمد، آتشی که طلا از طریقش خالص شد."),
            StoryParagraph("For Dostoevsky, suffering was not a curse but a blessing, not a punishment but a gift, the only means by which the human soul could be awakened from its slumber.", "برای داستایفسکی، رنج نفرین نبود بلکه برکت بود، نه مجازات بلکه موهبت، تنها وسیله‌ای که روح انسان می‌توانست با آن از خوابش بیدار شود."),
            StoryParagraph("The comfortable man, the man who has never suffered, lives in a kind of sleep; he does not know himself, he does not know the world, he does not know the depths that lie beneath the surface of ordinary life.", "مرد راحت، مردی که هرگز رنج نکشیده، در نوعی خواب زندگی می‌کند؛ خودش را نمی‌شناسد، دنیا را نمی‌شناسد، اعماقی که زیر سطح زندگی معمولی نهفته است را نمی‌شناسد."),
            StoryParagraph("It is only through suffering that we are awakened; only through suffering that we come to know who we truly are; only through suffering that we learn to love.", "تنها از طریق رنج است که بیدار می‌شویم؛ تنها از طریق رنج است که به دانستن اینکه واقعاً کی هستیم می‌رسیم؛ تنها از طریق رنج است که یاد می‌گیریم دوست بداریم."),
            StoryParagraph("This is the deepest paradox of Dostoevsky's Christianity: that suffering, which seems to be the greatest evil, is in fact the greatest good, for it is the only path to redemption.", "این عمیق‌ترین پارادوکس مسیحیت داستایفسکی است: رنج که به نظر می‌رسد بزرگ‌ترین شر باشد، در واقع بزرگ‌ترین خیر است، چون تنها راه رستگاری است."),
            StoryParagraph("Raskolnikov had to kill two women to learn this; he had to destroy his own life to discover that life was worth living; he had to descend into hell to find the way to heaven.", "راسکولنیکوف مجبور بود دو زن را بکشد تا این را بیاموزد؛ مجبور بود زندگی خودش را نابود کند تا کشف کند که زندگی ارزش زیستن دارد؛ مجبور بود به جهنم نزول کند تا راه بهشت را بیابد."),
            StoryParagraph("But learn it he did, discover it he did, find it he did, and in the end, the man who had begun as a murderer became a man capable of love.", "اما آموخت، کشف کرد، یافت و در نهایت، مردی که به عنوان قاتل آغاز شده بود، مردی شد که قادر به عشق بود."),
            StoryParagraph("This is the miracle that Dostoevsky celebrates: not the miracle of resurrection, which is supernatural, but the miracle of transformation, which is entirely human.", "این معجزه‌ای است که داستایفسکی جشن می‌گیرد: نه معجزه رستاخیز که فراطبیعی است، بلکه معجزه دگرگونی که کاملاً انسانی است."),
            StoryParagraph("The novel ends not with Raskolnikov's death, which would be a tragedy, but with his rebirth, which is a comedy in the oldest sense of the word — a story with a happy ending.", "رمان نه با مرگ راسکولنیکوف که تراژدی می‌بود، بلکه با تولد دوباره‌اش پایان می‌یابد که کمدی به قدیمی‌ترین معنای واژه است — داستانی با پایان خوش."),
            StoryParagraph("And this happy ending, which critics have sometimes dismissed as sentimental, is in fact the most profound and the most difficult of all endings, for it is the ending that requires the most faith.", "و این پایان خوش، که منتقدان گاهی آن را احساساتی خوانده‌اند، در واقع عمیق‌ترین و دشوارترین پایان‌هاست، چون پایانی است که بیشترین ایمان را می‌طلبد."),
            StoryParagraph("To believe that a murderer can become a saint, that a prostitute can be a redeemer, that a prison can be a path to freedom — this is the faith that Dostoevsky demands of his readers.", "باور به اینکه قاتلی می‌تواند قدیس شود، روسپی‌ای می‌تواند رستگارکننده باشد، زندانی می‌تواند راهی به آزادی باشد — این ایمانی است که داستایفسکی از خوانندگانش می‌طلبد."),
            StoryParagraph("And it is a faith that the modern world, with its cynicism and its despair, finds almost impossible to accept, for we have been taught to believe in nothing, to hope for nothing, to love nothing.", "و این ایمانی است که دنیای مدرن، با بدبینی و ناامیدی‌اش، تقریباً غیرممکن می‌یابد که بپذیرد، چون به ما آموخته‌اند که به هیچ چیز باور نکنیم، به هیچ چیز امید نبندیم، هیچ چیز را دوست نداشته باشیم."),
            StoryParagraph("But Dostoevsky, who had himself been sentenced to death and reprieved at the last moment, who had spent years in a Siberian prison, who had known suffering more intimately than most men, believed.", "اما داستایفسکی که خودش به مرگ محکوم شده و در آخرین لحظه بخشیده شده بود، که سال‌ها در زندانی سیبری گذرانده بود، که رنج را صمیمی‌تر از بیشتر مردان می‌شناخت، باور داشت."),
            StoryParagraph("He believed not despite his suffering but because of it; he believed because his suffering had taught him what no comfort could have taught; he believed because he had seen, with his own eyes, the miracle of redemption.", "نه به رغم رنجش باور داشت، بلکه به خاطر آن؛ باور داشت چون رنجش چیزی به او آموخته بود که هیچ راحتی نمی‌توانست بیاموزد؛ باور داشت چون با چشمان خودش معجزه رستگاری را دیده بود."),
            StoryParagraph("And so he wrote Crime and Punishment, not as a detective story, not as a psychological study, but as a gospel, a proclamation of the good news that no one is beyond saving.", "و اینگونه جنایات و مکافات را نوشت، نه به عنوان داستان کارآگاهی، نه به عنوان مطالعه روانشناختی، بلکه به عنوان انجیل، اعلام خبر خوش که هیچ‌کس فراتر از نجات نیست."),
            StoryParagraph("This is why the novel has endured, why it speaks to every generation, why it continues to move readers who have no interest in Russian literature or Orthodox theology.", "این است که چرا رمان دوام آورده، چرا با هر نسلی صحبت می‌کند، چرا همچنان خوانندگانی را که هیچ علاقه‌ای به ادبیات روسی یا الهیات ارتدکس ندارند متأثر می‌کند."),
            StoryParagraph("Because it speaks to something universal, something that lies at the very core of what it means to be human: the need to believe that we can be better, that we can be forgiven, that we can be loved.", "چون به چیزی جهانی صحبت می‌کند، چیزی که در هسته اصلی آنچه انسان بودن را معنا می‌بخشد نهفته است: نیاز به باور به اینکه می‌توانیم بهتر باشیم، می‌توانیم بخشیده شویم، می‌توانیم دوست داشته شویم."),
            StoryParagraph("And this need, which the modern world mocks and denies, is the deepest need of the human heart, the need that neither reason nor science nor progress can satisfy.", "و این نیاز، که دنیای مدرن مسخره می‌کند و انکارش می‌کند، عمیق‌ترین نیاز قلب انسان است، نیازی که نه عقل، نه علم، نه پیشرفت نمی‌توانند ارضایش کنند."),
            StoryParagraph("Raskolnikov is not a monster; he is every man who has ever believed himself superior to others, every man who has ever thought himself entitled to act in ways that others are not.", "راسکولنیکوف هیولا نیست؛ او هر مردی است که تا حالا خودش را برتر از دیگران پنداشته، هر مردی که تا حالا فکر کرده مجاز است به شیوه‌هایی عمل کند که دیگران نیستند."),
            StoryParagraph("Sonia is not a saint; she is every woman who has ever sacrificed herself for others, every woman who has ever loved without expectation of return, every woman who has ever believed in the goodness of God.", "سونیا قدیس نیست؛ او هر زنی است که تا حالا خودش را برای دیگران فدا کرده، هر زنی که تا حالا بدون انتظار بازگشت عشق ورزیده، هر زنی که تا حالا به نیکی خدا باور داشته."),
            StoryParagraph("Porfiry is not a wise man; he is every teacher who has ever waited patiently for his student to learn, every father who has ever let his child fall, every friend who has ever loved enough to let go.", "پورفیری مرد فرزانه‌ای نیست؛ او هر معلمی است که تا حالا صبورانه منتظر مانده تا شاگردش بیاموزد، هر پدری که تا حالا گذاشته فرزندش بیفتد، هر دوستی که تا حالا به اندازه کافی دوست داشته که رها کند."),
            StoryParagraph("And Marmeladov is not a fool; he is every man who has ever destroyed himself and known that he was doing it, every man who has ever wept over his own weakness, every man who has ever hoped, against all hope, for mercy.", "و مارملادوف احمق نیست؛ او هر مردی است که تا حالا خودش را نابود کرده و می‌دانسته که دارد این کار را می‌کند، هر مردی که تا حالا بر ضعف خودش گریسته، هر مردی که تا حالا برخلاف همه امید، به رحمت امید بسته."),
            StoryParagraph("This is the genius of Dostoevsky: that he does not create characters, but archetypes; that he does not tell a story, but preaches a sermon; that he does not entertain, but transforms.", "این نابغگی داستایفسکی است: او شخصیت نمی‌سازد، بلکه کهن‌الگو می‌سازد؛ داستان نمی‌گوید، بلکه موعظه می‌کند؛ سرگرم نمی‌کند، بلکه دگرگون می‌کند."),
            StoryParagraph("And in reading him, we are not merely reading a novel; we are being invited to confront the deepest questions of our own existence, the questions we have spent our lives avoiding.", "و در خواندن او، فقط رمان نمی‌خوانیم؛ دعوت می‌شویم که با عمیق‌ترین پرسش‌های وجود خودمان روبرو شویم، پرسش‌هایی که تمام عمرمان از آنها گریخته‌ایم."),
            StoryParagraph("Who am I? What have I done? What can I become? These are the questions that Dostoevsky asks, and they are the questions that every human being must answer, sooner or later, alone.", "من کی هستم؟ چه کرده‌ام؟ چه می‌توانم شوم؟ اینها پرسش‌هایی هستند که داستایفسکی می‌پرسد و پرسش‌هایی هستند که هر انسانی باید پاسخ دهد، دیر یا زود، تنها."),
            StoryParagraph("And so Crime and Punishment ends, not with a conclusion but with an invitation, not with an answer but with a hope, not with a period but with an ellipsis.", "و اینگونه جنایات و مکافات پایان می‌یابد، نه با نتیجه‌گیری بلکه با دعوت، نه با پاسخ بلکه با امید، نه با نقطه بلکه با سه‌نقطه."),
            StoryParagraph("The story of Raskolnikov is over, but the story of the reader is just beginning, and the question that Dostoevsky leaves us with is this: what will we do with the love that has been given us?", "داستان راسکولنیکوف تمام شده، اما داستان خواننده تازه آغاز می‌شود و پرسشی که داستایفسکی با آن رهایمان می‌کند این است: با عشقی که به ما داده شده چه خواهیم کرد؟"),
            StoryParagraph("Will we accept it, as Sonia accepted it? Will we offer it, as Sonia offered it? Will we allow it to transform us, as it transformed Raskolnikov? Or will we reject it, and return to the darkness?", "آیا می‌پذیریم، همانطور که سونیا پذیرفت؟ آیا عرضه‌اش می‌کنیم، همانطور که سونیا عرضه کرد؟ آیا می‌گذاریم دگرگونمان کند، همانطور که راسکولنیکوف را دگرگون کرد؟ یا ردش می‌کنیم و به تاریکی بازمی‌گردیم؟"),
            StoryParagraph("The answer is not in the novel; the answer is in our lives. The novel has shown us the way; the rest is up to us.", "پاسخ در رمان نیست؛ پاسخ در زندگی‌مان است. رمان راه را به ما نشان داده؛ بقیه‌اش به عهده ماست."),
            StoryParagraph("That is the terrible freedom that Dostoevsky gives us: the freedom to choose, the freedom to love, the freedom to be saved. And the terrible responsibility that comes with it.", "این همان آزادی هولناکی است که داستایفسکی به ما می‌دهد: آزادی انتخاب، آزادی عشق، آزادی نجات. و مسئولیت هولناکی که همراهش می‌آید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("Or, perhaps, the beginning.", "یا، شاید، آغاز.")
        )
    )
}